			t.Fatalf("removed hash %s still indexed", hash)
		}
	}
	if _, ok := index.Blocks[2].Hash, index.Blocks[2]; !ok || index.Blocks[2].Hash != "h2b" {
		t.Fatalf("height 2 not replaced: %+v", index.Blocks[2])
